import six
from abc import ABCMeta, abstractmethod
from functools import partial
from taf.ue.plugin.mtk.exceptions import UnsupportedPDN


class Configuration(object):
    _instance = None
    _pdn_config = {}

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super(Configuration, cls).__new__(cls)
        return cls._instance

    def __init__(self, config_adapter=None):
        if config_adapter:
            self._adapter = config_adapter
            self._adapter.update_config(self._pdn_config)
            for name, method in type(self._adapter).__dict__.items():
                if not name.startswith("_"):
                    self.__dict__[name] = partial(method, self._adapter)
            self._pdn_config = self._adapter.get_config()


@six.add_metaclass(ABCMeta)
class ConfigAdapter(object):

    @abstractmethod
    def get_pdn_names(self):
        pass

    @abstractmethod
    def get_apn(self, *args):
        pass

    @abstractmethod
    def get_pdp_type(self, *args):
        pass


class ConfigAdapter545(ConfigAdapter):
    def __init__(self, device_config):
        self._config = device_config  # Not contain PDN config, need to use default config

    def get_pdn_names(self):
        return ["default"]

    def get_apn(self, pdn_name):
        if pdn_name == "default":
            return self._config['CONSTRUCTOR_PARAMETERS']['configuration']["data_transfer"]["apn"]["url"]
        raise UnsupportedPDN("Unsupported PDN name:{}".format(pdn_name))

    def get_pdp_type(self, pdn_name):
        return "IPV4V6"


class ConfigAdapter590(ConfigAdapter):
    def __init__(self, pdn_config):
        self._config = pdn_config  # Contains PDN config

    def get_config(self):
        return self._config

    def update_config(self, pdn_config):
        self._config.update(pdn_config)

    def get_pdn_names(self):
        return self._config.keys()

    def get_apn(self, pdn_name):
        return self._config[pdn_name]["apn"]

    def get_pdp_type(self, pdn_name):
        return self._config[pdn_name]["pdp_type"]
